import json,shutil
from run import R,OLD,LINT,WS,sha
sources=[]
def copy(source,target):
 assert not target.exists();target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(source,target);sources.append({'source':str(source),'target':target.relative_to(R).as_posix(),'sha256':sha(target)})
for file in ['nest-cli.json','tsconfig.json','src/main.ts']:copy(OLD/'workspace/api'/file,WS/'api'/file)
for file in ['lint-config.mjs','check_effective.mjs','test_rules.mjs','test_coverage.mjs','check_final.mjs']:copy(LINT/'workspace'/file,WS/file)
for app in ['web','admin']:
 for file in ['app/page.tsx','app/layout.tsx','app/client-probe.tsx','app/globals.css','postcss.config.mjs','next.config.mjs']:copy(OLD/'workspace'/app/file,WS/app/file)
 for file in ['eslint.config.mjs','probe-settings.js','src/controls.tsx','src/error-boundary.tsx','src/values.ts','src/server/only.ts']:copy(LINT/'workspace'/app/file,WS/app/file)
 (WS/app/'fixtures').mkdir()
 config=json.loads((OLD/'workspace'/app/'tsconfig.json').read_text());config['compilerOptions']['paths']={'@/*':['./src/*']};config['exclude']=['node_modules','fixtures'];(WS/app/'tsconfig.json').write_text(json.dumps(config,indent=2)+'\n')
(R/'evidence/synthetic-inputs.json').write_text(json.dumps({'copied_owned_samples':sources,'composition':'Original build app/page, layout, client and styles plus original lint support src/config. Negative lint fixtures are explicitly excluded from the build typecheck, not silently accepted as clean application code. No rule/config weakening.','typescript':'original strict Next config plus lint alias; skipLibCheck false'},indent=2)+'\n')
print('Prepared',len(sources),'owned sample/config/check copies; no reference code or old installed graph copied')

