"use client";
import { Component, type ReactNode } from 'react';
export class ProbeBoundary extends Component<{ children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  render() { return this.state.failed ? <p role="alert">Synthetic failure</p> : this.props.children; }
}

